const fs = require('fs');
const promptBase = '/workspace/groupscout/docs/mvps/mvp-b/prompts';
const readPrompt = (name) => fs.readFileSync(`${promptBase}/${name}`, 'utf8').trim();
return {
  system_brand_voice: readPrompt('system_brand_voice.txt'),
  user_classify: readPrompt('user_classify.txt'),
  user_sequence_commercial: readPrompt('user_sequence_commercial.txt'),
  user_sequence_residential: readPrompt('user_sequence_residential.txt'),
  user_slack_notify: readPrompt('user_slack_notify.txt')
};

const raw = $input.first().json.content[0].text;

const parseJSON = (text) => {
  const trimmed = String(text || '').trim();

  try {
    return JSON.parse(trimmed);
  } catch (err) {
    const fenced = trimmed.match(/```(?:json)?\n?([\s\S]*?)\n?```/);
    if (fenced) return JSON.parse(fenced[1]);

    const start = trimmed.search(/[\[{]/);
    const lastObject = trimmed.lastIndexOf('}');
    const lastArray = trimmed.lastIndexOf(']');
    const end = Math.max(lastObject, lastArray);
    if (start !== -1 && end !== -1 && end >= start) {
      return JSON.parse(trimmed.slice(start, end + 1));
    }

    throw err;
  }
};

const parsed = parseJSON(raw);
return {
  lead_tier: parsed.lead_tier,
  project_category: parsed.project_category,
  key_detail: parsed.key_detail,
  urgency_signal: parsed.urgency_signal
};

// Build enriched context object for sequence prompt and Slack notification
const classification = $input.first().json;
const lead = $('Webhook').first().json.body || $('Webhook').first().json;

const normalizedLeadTier = String(classification.lead_tier || 'medium').trim().toLowerCase() || 'medium';
const normalizedProjectCategory = String(classification.project_category || 'unknown').trim().toLowerCase() || 'unknown';
const keyDetail = typeof classification.key_detail === 'string' ? classification.key_detail.trim() : '';
const urgencySignal = Boolean(classification.urgency_signal);

return {
  lead_json: JSON.stringify(lead),
  lead_tier: normalizedLeadTier,
  project_category: normalizedProjectCategory,
  key_detail: keyDetail || null,
  key_detail_for_prompt: keyDetail || 'none provided',
  urgency_signal: urgencySignal,
  lead_context_json: JSON.stringify({
    name: lead.name,
    company: lead.company || null,
    project_type: lead.project_type,
    budget_range: lead.budget_range,
    timeline: lead.timeline,
    lead_tier: normalizedLeadTier,
    urgency_signal: urgencySignal,
    key_detail: keyDetail || null
  })
};

